const axios = require("axios");

const API = "https://downvid.onrender.com/api/download";

/**
 * Download video & audio using downvid API
 * @param {string} url
 * @returns {Promise<{title:string, video:string, audio:string, thumbnail:string}>}
 */
async function downvid(url) {
  if (!url) throw new Error("URL is required");

  const res = await axios.get(
    `${API}?url=${encodeURIComponent(url)}`
  );

  if (res.data.status !== "success") {
    throw new Error("Failed to download media");
  }

  return {
    title: res.data?.data?.data?.title || null,
    video: res.data.video || null,
    audio: res.data.audio || null,
    thumbnail: res.data?.data?.data?.img_src || null
  };
}

module.exports = downvid;